def solve(inp, name=None):
    a=np.array(inp); H,W=a.shape
    c=Counter(v for row in inp for v in row)
    bg=max(c.items(),key=lambda x:x[1])[0]
    occ=[v for v in c if v!=bg]
    visited=set(); comps=[]
    for r in range(H):
        for col in range(W):
            if a[r][col]==0 and (r,col) not in visited:
                q=[(r,col)]; visited.add((r,col)); cells=[]
                while q:
                    nr,nc=q.pop(); cells.append((nr,nc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nn=(nr+dr,nc+dc)
                        if 0<=nn[0]<H and 0<=nn[1]<W and a[nn[0]][nn[1]]==0 and nn not in visited:
                            visited.add(nn); q.append(nn)
                comps.append(cells)

    outa=np.array(G[name+'_output'] if f'{name}_output' in G else None)
    if outa is None: return None, False, {}
    outchanged = [(r,c) for r in range(H) for c in range(W) if a[r,c]!=outa[r,c] and a[r,c]==0]

    # For each interior (border-free) comp, check if ANY of its cells changed
    interior_comps = [cells for cells in comps if not any(p[0] in (0,H-1) or p[1] in (0,W-1) for p in cells)]
    result = [row[:] for row in inp]
    filled_ok = True
    mismatches = []
    for cells in interior_comps:
        changed_in_comp = any((r,c) in outchanged for (r,c) in cells)
        if changed_in_comp:
            # mark all cells in this comp as filled
            for r,c in cells:
                result[r][c]=occ[0]
        else:
            # check any cell in this comp changed unexpectedly
            for r,c in cells:
                if a[r,c]!=outa[r,c]:
                    filled_ok=False
                    mismatches.append(((r,c),(r,c)))  # marker
    return result, filled_ok, {len(comps): len(interior_comps)}

