G=load()

def f(inp):
    import numpy as np
    from collections import deque,Counter
    a=np.array(inp); H,W=a.shape
    c=Counter(v for row in inp for v in row)
    bg=max(c.items(),key=lambda x:x[1])[0]
    nonbg=[v for v in c if v!=bg]; spec=min(nonbg,key=lambda x:c[x])
    visited=set(); comps=[]
    for r in range(H):
        for col in range(W):
            if a[r][col]==0 and (r,col) not in visited:
                q=[(r,col)]; visited.add((r,col)); cells=[]
                while q:
                    nr,nc=q.pop(); cells.append((nr,nc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nn=(nr+dr,nc+dc)
                        if 0<=nn[0]<H and 0<=nn[1]<W and a[nn[0]][nn[1]]==0 and nn not in visited:
                            visited.add(nn); q.append(nn)
                comps.append(cells)
    result=[row[:] for row in inp]
    for idx,cells in enumerate(comps):
        border=any(p[0] in (0,H-1) or p[1] in (0,W-1) for p in cells)
        if not border:
            for r,c in cells: result[r][c]=spec
    return result

